#include <set>
#include "native_material_init.hpp"
#include <cassert>
#include <cstdio>
int main(int argc,char**argv){assert(argc==2);WiiAssets disc(std::filesystem::u8path(argv[1]));Rarc archive(disc.readFile("/ObjectData/Mario.arc"));size_t checked=0;for(const auto&file:archive.files){auto bytes=archive.readFile(file.path);if(bytes.size()<32 || std::memcmp(bytes.data(),"J3D2",4))continue;size_t pos=32;for(unsigned i=0;i<be32(bytes.data()+12);++i){extent(pos,8,bytes.size());auto length=be32(bytes.data()+pos+4);extent(pos,length,bytes.size());if(!std::memcmp(bytes.data()+pos,"MAT3",4)){NativeMaterialHeader header(bytes.data()+pos,length);assert(header.materialCount>0);NativeMaterialInitTables tables(bytes.data()+pos,length);assert(!tables.records.empty());J3DMaterialFactory factory(tables);std::set<uint16_t> unique(tables.header.remap.begin(),tables.header.remap.end());assert(factory.countUniqueMaterials()==unique.size());for(unsigned m=0;m<header.materialCount;++m){auto& init=tables.records[header.remap[m]];unsigned texgens=init.mTexGenNumIdx==255?0:tables.texGenCounts[init.mTexGenNumIdx];unsigned stages=init.mTevStageNumIdx==255?0:tables.tevStageCounts[init.mTevStageNumIdx];assert(factory.newColorChanNum(m)==(init.mColorChanNumIdx==255?0:tables.colorChannelCounts[init.mColorChanNumIdx])); assert(factory.newTexGenNum(m)==texgens); assert(factory.newCullMode(m)==(init.mCullModeIdx==255?255:tables.cullModes[init.mCullModeIdx])); assert(factory.newTevStageNum(m)==(init.mTevStageNumIdx==255?255:stages)); assert(factory.newZCompLoc(m)==(init.mZCompLocIdx==255?0:tables.depthCompareLocations[init.mZCompLocIdx])); assert(factory.newDither(m)==(init.mDitherIdx==255?1:tables.ditherFlags[init.mDitherIdx])); for(unsigned slot=0;slot<8;++slot)assert(factory.newTexNo(m,slot)==(init.mTexNoIdx[slot]==65535?65535:tables.textureNumbers[init.mTexNoIdx[slot]])); unsigned textures=0;for(auto index:init.mTexNoIdx)if(index!=65535)++textures;assert(factory.countTexGens(m)==texgens && factory.countStages(m)==std::max(stages,textures));}assert(factory.mMaterialNum==header.materialCount && factory.mpMaterialInitData==tables.records.data() && factory.mpMaterialID==tables.header.remap.data() && factory.mpTexNo==tables.textureNumbers.data() && factory.mpTexMtxInfo==tables.textureMatrices.data() && factory.mpTevStageInfo==tables.tevStages.data());for(size_t t=0;t<tables.indirect.size();++t){auto raw=bytes.data()+pos+header.offsets[3]+t*0x138;assert(tables.indirect[t].mEnabled==(raw[0]!=0) && tables.indirect[t].mIndTexStageNum==raw[1]);for(unsigned m=0;m<3;++m)for(unsigned row=0;row<2;++row)for(unsigned col=0;col<3;++col){uint32_t bits;std::memcpy(&bits,&tables.indirect[t].mIndTexMtxInfo[m].field_0x0[row][col],4);assert(bits==be32(raw+20+m*28+(row*3+col)*4));}}std::printf("PASS indirect records: %zu\n",tables.indirect.size());for(size_t t=0;t<tables.textureMatrices.size();++t){auto raw=bytes.data()+pos+header.offsets[13]+t*0x64;auto& matrix=tables.textureMatrices[t];uint32_t bits;std::memcpy(&bits,&matrix.mSRT.mScaleX,4);assert(bits==be32(raw+16));assert(uint16_t(matrix.mSRT.mRotation)==(uint16_t(raw[24])<<8|raw[25]));for(unsigned row=0;row<4;++row)for(unsigned col=0;col<4;++col){std::memcpy(&bits,&matrix.mEffectMtx[row][col],4);assert(bits==be32(raw+36+(row*4+col)*4));}}for(size_t t=0;t<tables.fog.size();++t){auto raw=bytes.data()+pos+header.offsets[23]+t*0x2c;auto& fog=tables.fog[t];uint32_t bits;std::memcpy(&bits,&fog.mStartZ,4);assert(bits==be32(raw+4));assert(fog.mCenter==(uint16_t(raw[2])<<8|raw[3]));for(unsigned j=0;j<10;++j)assert(fog.mFogAdjTable.r[j]==(uint16_t(raw[24+j*2])<<8|raw[25+j*2]));}for(size_t t=0;t<tables.nbtScales.size();++t){auto raw=bytes.data()+pos+header.offsets[29]+t*16;uint32_t bits;std::memcpy(&bits,&tables.nbtScales[t].mScale.x,4);assert(bits==be32(raw+4));}assert(tables.alphaTests.empty() || !std::memcmp(tables.alphaTests.data(),bytes.data()+pos+header.offsets[24],tables.alphaTests.size()*sizeof(J3DAlphaCompInfo)));assert(tables.blends.empty() || !std::memcmp(tables.blends.data(),bytes.data()+pos+header.offsets[25],tables.blends.size()*sizeof(J3DBlendInfo)));assert(tables.depthModes.empty() || !std::memcmp(tables.depthModes.data(),bytes.data()+pos+header.offsets[26],tables.depthModes.size()*sizeof(J3DZModeInfo)));assert(tables.tevStages.empty() || !std::memcmp(tables.tevStages.data(),bytes.data()+pos+header.offsets[20],tables.tevStages.size()*sizeof(J3DTevStageInfo)));assert(tables.tevOrders.empty() || !std::memcmp(tables.tevOrders.data(),bytes.data()+pos+header.offsets[16],tables.tevOrders.size()*sizeof(J3DTevOrderInfo)));assert(tables.texCoords.empty() || !std::memcmp(tables.texCoords.data(),bytes.data()+pos+header.offsets[11],tables.texCoords.size()*sizeof(J3DTexCoordInfo)));for(size_t t=0;t<tables.materialColors.size();++t){auto raw=bytes.data()+pos+header.offsets[5]+t*4;auto color=tables.materialColors[t];assert(color.r==raw[0] && color.g==raw[1] && color.b==raw[2] && color.a==raw[3]);}for(size_t t=0;t<tables.textureNumbers.size();++t){auto raw=bytes.data()+pos+header.offsets[15]+t*2;assert(tables.textureNumbers[t]==(uint16_t(raw[0])<<8|raw[1]));}for(size_t t=0;t<tables.cullModes.size();++t)assert(tables.cullModes[t]==be32(bytes.data()+pos+header.offsets[4]+t*4));for(size_t r=0;r<tables.records.size();++r){auto raw=bytes.data()+pos+header.offsets[0]+r*0x14c;auto half=[&](size_t offset){return uint16_t(raw[offset])<<8|raw[offset+1];};assert(tables.records[r].mMaterialMode==raw[0]);for(unsigned j=0;j<8;++j){assert(tables.records[r].mTexNoIdx[j]==half(0x84+j*2));assert(tables.records[r].mTexMtxIdx[j]==half(0x48+j*2));}for(unsigned j=0;j<16;++j)assert(tables.records[r].mTevStageIdx[j]==half(0xe4+j*2));assert(tables.records[r].mFogIdx==half(0x144));assert(!std::memcmp(tables.records[r].field_0x058,raw+0x58,0x2c));}auto broken=std::vector<uint8_t>(bytes.begin()+pos,bytes.begin()+pos+length);std::memset(broken.data()+12,0xff,4);bool rejected=false;try{NativeMaterialHeader invalid(broken.data(),broken.size());}catch(const std::runtime_error&){rejected=true;}assert(rejected);assert(header.remap.size()==header.materialCount);for(size_t index=0;index<header.remap.size();++index){auto at=pos+header.offsets[1]+index*2;assert(header.remap[index]==(uint16_t(bytes[at])<<8|bytes[at+1]));}broken.assign(bytes.begin()+pos,bytes.begin()+pos+length);broken[header.offsets[1]]=0xff;broken[header.offsets[1]+1]=0xff;rejected=false;try{NativeMaterialHeader invalid(broken.data(),broken.size());}catch(const std::runtime_error&){rejected=true;}assert(rejected);broken.assign(bytes.begin()+pos,bytes.begin()+pos+length);broken[header.offsets[0]+0x84]=0xff;broken[header.offsets[0]+0x85]=0xfe;rejected=false;try{NativeMaterialInitTables invalid(broken.data(),broken.size());}catch(const std::runtime_error&){rejected=true;}assert(rejected);if(header.offsets[17]){broken.assign(bytes.begin()+pos,bytes.begin()+pos+length);broken[header.offsets[17]]=0xff;broken[header.offsets[17]+1]=0xfe;NativeMaterialInitTables signedColors(broken.data(),broken.size());assert(!signedColors.tevColors.empty() && signedColors.tevColors[0].r==-2);}broken.assign(bytes.begin()+pos,bytes.begin()+pos+length);broken[header.offsets[0]+0x148]=0xff;broken[header.offsets[0]+0x149]=0xfe;rejected=false;try{NativeMaterialInitTables invalid(broken.data(),broken.size());}catch(const std::runtime_error&){rejected=true;}assert(rejected);++checked;std::printf("PASS MAT3 %s: %u materials, bounded offsets\n",file.path.c_str(),header.materialCount);}pos+=length;}}assert(checked>0);}













